function exploreUrl(resource, search = '') {
	return `${repositoryPageUrl(REPOSITORY_ID, 'explore')}?resource=${encodeURIComponent(`<${resource}>`)}${search}`;
}

async function screenshot(page, name) {
	if (EVIDENCE_DIR || evidenceScreenshots()) {
		await page.screenshot({ path: evidencePath(EVIDENCE_DIR, `${test.info().project.name}-${name}.png`), fullPage: true });
	}
}

/** The page never scrolls sideways, and every shared table stays inside its card or scrolls in its own box. */
async function overflowMetrics(page, section) {
	return page.evaluate((selector) => {
		const scroller = document.scrollingElement;
		const card = document.querySelector(selector);
		const cardBox = card ? card.getBoundingClientRect() : null;
		const tables = [];
		for (const layout of card ? card.querySelectorAll('.query-result-layout') : []) {
			const wrap = layout.querySelector(':scope > .query-result-table-wrap');
			const table = wrap && wrap.querySelector('table.data');
			const layoutBox = layout.getBoundingClientRect();
			tables.push({
				effectiveLayout: layout.getAttribute('data-effective-layout'),
				layoutRight: layoutBox.right,
				wrapRight: wrap && !wrap.hidden ? wrap.getBoundingClientRect().right : null,
				wrapScrolls: !!wrap && wrap.scrollWidth > wrap.clientWidth + 1
					&& ['auto', 'scroll'].includes(getComputedStyle(wrap).overflowX),
				tableRight: table && !wrap.hidden ? table.getBoundingClientRect().right : null
			});
		}
		return {
			scrollWidth: scroller.scrollWidth,
			clientWidth: scroller.clientWidth,
			cardRight: cardBox ? cardBox.right : null,
			tables
		};
	}, section);
}

function expectContained(metrics, label) {
	expect(metrics.scrollWidth, `${label}: the page does not scroll sideways`).toBeLessThanOrEqual(metrics.clientWidth + 1);
	expect(metrics.tables.length, `${label}: the statements are shown by the shared result table`).toBeGreaterThan(0);
	for (const [index, table] of metrics.tables.entries()) {
		expect(table.layoutRight, `${label} table ${index}: stays inside its card`).toBeLessThanOrEqual(metrics.cardRight + 1);
		if (table.tableRight !== null) {
			expect(table.wrapRight, `${label} table ${index}: its scroll box stays inside the card`)
				.toBeLessThanOrEqual(metrics.cardRight + 1);
			expect(table.tableRight <= table.wrapRight + 1 || table.wrapScrolls,
				`${label} table ${index}: fits its box or scrolls inside it ${JSON.stringify(table)}`).toBe(true);
		}
	}
}

/** Rows of a shared table, in its table or its records layout. */
function sharedRows(scope) {
	return scope.locator(':is(.query-result-table-wrap:not([hidden]) table.data tbody tr, '
		+ '.query-result-records:not([hidden]) .query-result-record)[data-workbench-row-index]');
}

test('Explore groups use the shared result table on a desktop', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await page.goto(exploreUrl(RESOURCE), { waitUntil: 'domcontentloaded' });
	await waitForRoute(page, 'explore');
	const outgoing = page.locator('section.explore-group[data-explore-role="outgoing"]');
	await expect(outgoing.locator('.query-result-layout table.data tbody tr[data-workbench-row-index]').first())
		.toBeVisible({ timeout: 15_000 });
	await screenshot(page, 'explore-desktop');

	expectContained(await overflowMetrics(page, '#explore-results'), 'Explore 1440px');
	await expect(outgoing.locator('.query-result-layout')).toHaveAttribute('data-effective-layout', 'table');
	await expect(outgoing.locator('.query-result-table-wrap thead th')).toHaveText(['Predicate', 'Object', 'Graph']);
	await expect(page.locator('section.explore-group[data-explore-role="predicate"] .query-result-table-wrap thead th'))
		.toHaveText(['Subject', 'Object']);
	await expect(page.locator('section.explore-group[data-explore-role="graph"] .query-result-table-wrap thead th'))
		.toHaveText(['Subject', 'Predicate', 'Object']);
	await expect(sharedRows(outgoing)).toHaveCount(10);
	await expect(outgoing.locator('td[data-label="Graph"]').filter({ hasText: /^Default graph$/ })).toHaveCount(1);

	// Long IRIs break after / # : like the Query page's cells, and stay inside their cell.
	const part = outgoing.locator(`td[data-label="Object"] a[href*="${encodeURIComponent('/part/')}"]`).first();
	await expect(part).toBeVisible();
	const geometry = await part.evaluate(link => {
		const cell = link.closest('td');
		return {
			breaks: link.querySelectorAll('wbr').length,
			linkRight: link.getBoundingClientRect().right,
			cellRight: cell.getBoundingClientRect().right
		};
	});
	expect(geometry.breaks, 'the IRI has line-break opportunities').toBeGreaterThan(0);
	expect(geometry.linkRight, 'the IRI stays inside its cell').toBeLessThanOrEqual(geometry.cellRight + 1);

	// Literal tags and the Display panel's Show datatypes switch, as on the Query page.
	const dateTag = outgoing.locator('.rdf-datatype').filter({ hasText: 'date' });
	await expect(dateTag).toBeVisible();
	await expect(outgoing.locator('.rdf-language').filter({ hasText: '@en' })).toBeVisible();
	await expect(outgoing.locator('td.rdf-numeric')).toHaveCount(1);
	await page.locator('#explore-result-options-toggle').click();
	await page.locator('#explore-show-datatypes').uncheck();
	await expect(page.locator('#explore-results .rdf-datatype')).toHaveCount(0);
	await page.locator('#explore-show-datatypes').check();
	await expect(dateTag).toBeVisible();
	await page.locator('#explore-result-options-toggle').click();

	// Every term links to its own Explore page.
	const href = await part.getAttribute('href');
	expect(new URL(href, page.url()).searchParams.get('resource')).toBe(`<${PART}>`);
	await part.click();
	await waitForRoute(page, 'explore', { url: url => url.searchParams.get('resource') === `<${PART}>` });
	await expect(page.locator('#resource')).toHaveValue(`<${PART}>`);
	await expect(sharedRows(page.locator('section.explore-group[data-explore-role="incoming"]'))).toHaveCount(1);
});

