/** How the multi-line literal cells of a shared table lay out (C27): no <pre>, their link, tags and line breaks. */
async function multiLineCells(scope) {
	// Only the shown layout: the hidden table keeps its last rows while the records are shown.
	return scope.evaluate(root => Array.from(root.querySelectorAll(':is(td, dd).rdf-literal'))
		.filter(cell => cell.getClientRects().length > 0).map(cell => {
			const link = cell.querySelector('a[href^="explore?resource="]');
			const iriLink = cell.closest('tr, .query-result-record').querySelector('a[href^="explore?resource=%3C"]');
			const style = link ? getComputedStyle(link) : null;
			const cellBox = cell.getBoundingClientRect();
			const linkBox = link ? link.getBoundingClientRect() : null;
			return {
				text: cell.textContent,
				pre: cell.querySelectorAll('pre').length,
				linked: !!link,
				whiteSpace: style && style.whiteSpace,
				sameFont: !!link && !!iriLink && style.fontFamily === getComputedStyle(iriLink).fontFamily,
				lines: link ? Math.round(linkBox.height / parseFloat(style.lineHeight)) : 0,
				offset: link ? linkBox.top - cellBox.top : null,
				inside: !!link && linkBox.right <= cellBox.right + 1,
				tag: (cell.querySelector('.rdf-language, .rdf-datatype') || { textContent: '' }).textContent
			};
		}));
}

function expectMultiLineCells(cells, where) {
	expect(cells.length, `${where}: two multi-line literal cells`).toBe(2);
	for (const cell of cells) {
		expect.soft(cell.pre, `${where}: no bare <pre> in ${JSON.stringify(cell)}`).toBe(0);
		expect.soft(cell.linked, `${where}: the literal links to Explore`).toBe(true);
		expect.soft(cell.whiteSpace, `${where}: line breaks are kept and long lines wrap`).toBe('pre-wrap');
		expect.soft(cell.sameFont, `${where}: the literal is in the cell font`).toBe(true);
		expect.soft(cell.offset, `${where}: the value starts at the top of its cell`).toBeLessThanOrEqual(14);
		expect.soft(cell.inside, `${where}: the value stays inside its cell`).toBe(true);
	}
	const poem = cells.find(cell => cell.text.includes('first line'));
	const gedicht = cells.find(cell => cell.text.includes('erste Zeile'));
	expect.soft(poem && poem.lines, `${where}: three lines stay three lines`).toBeGreaterThanOrEqual(3);
	expect.soft(gedicht && gedicht.lines, `${where}: two lines stay two lines`).toBeGreaterThanOrEqual(2);
	expect.soft(gedicht && gedicht.tag, `${where}: the language tag stays`).toBe('@de');
}

// C27: a literal with line breaks is a cell like the others: its value keeps the breaks (pre-wrap) in the cell font,
// links to Explore and keeps its language tag, in the table and the records, on Explore and on the Query page, in the
// light theme (desktop) and the dark theme (phone).
test('multi-line literals keep their line breaks in the cell font, with their link and tags', async ({ page }) => {
	for (const viewport of [{ name: 'desktop', width: 1440, height: 900, theme: 'light' },
		{ name: 'phone', width: 390, height: 844, theme: 'dark' }]) {
		await page.setViewportSize({ width: viewport.width, height: viewport.height });
		await page.goto(exploreUrl(POEM), { waitUntil: 'domcontentloaded' });
		await waitForRoute(page, 'explore');
		await page.evaluate(theme => window.RDF4JWorkbenchTheme.setPreference(theme), viewport.theme);
		await expect(page.locator('html')).toHaveAttribute('data-theme', viewport.theme);
		const outgoing = page.locator('section.explore-group[data-explore-role="outgoing"]');
		await expect(sharedRows(outgoing)).toHaveCount(2, { timeout: 15_000 });
		await screenshot(page, `explore-multi-line-${viewport.name}`);
		expectContained(await overflowMetrics(page, '#explore-results'), `Explore multi-line ${viewport.name}`);
		expectMultiLineCells(await multiLineCells(outgoing), `Explore ${viewport.name}`);

		await openQueryPage(page, REPOSITORY_ID, { viewport: { width: viewport.width, height: viewport.height } });
		await runQuery(page, `SELECT ?p ?o WHERE { <${POEM}> ?p ?o } ORDER BY ?p`);
		const result = page.locator('#query-results .query-result-layout');
		await expect(result.locator('[data-query-row-index], [data-query-record-index]').first()).toBeVisible();
		await screenshot(page, `query-multi-line-${viewport.name}`);
		expectContained(await overflowMetrics(page, '#query-results'), `Query multi-line ${viewport.name}`);
		expectMultiLineCells(await multiLineCells(result), `Query ${viewport.name}`);

		// The same cells as records (the phone's layout for wider results).
		await result.locator('.query-result-toolbar__disclosures button').filter({ hasText: 'Display' }).click();
		await result.locator('select[name="result-layout"]').selectOption('records');
		await expect(result).toHaveAttribute('data-effective-layout', 'records');
		await expect(result.locator('.query-result-record')).toHaveCount(2);
		await screenshot(page, `query-multi-line-${viewport.name}-records`);
		expectContained(await overflowMetrics(page, '#query-results'), `Query multi-line records ${viewport.name}`);
		expectMultiLineCells(await multiLineCells(result), `Query records ${viewport.name}`);
	}
});

test('the Query page result table is unchanged', async ({ page }) => {
	await openQueryPage(page, REPOSITORY_ID, { viewport: { width: 1440, height: 900 } });
	await runQuery(page, `SELECT ?s ?p ?o WHERE { BIND(<${RESOURCE}> AS ?s) ?s ?p ?o } ORDER BY ?p`);
	const result = page.locator('#query-results .query-result-layout');
	await expect(result).toHaveAttribute('data-effective-layout', 'table');
	await expect(result.locator('.query-result-table-wrap thead th')).toHaveText(['?s', '?p', '?o']);
	await expect(result.locator('tbody tr[data-query-row-index]')).toHaveCount(10);
	await expect(result.locator('tbody td a:not(.resourceURL) wbr').first()).toBeAttached();
	await expect(result.locator('.rdf-datatype').filter({ hasText: 'date' })).toBeVisible();
	expectContained(await overflowMetrics(page, '#query-results'), 'Query results');
	await screenshot(page, 'query-desktop');
});

